// > 1024-byte js fixture to defeat the compression threshold
function greet(name) { return 'hello, ' + name + '! welcome to compression land.'; }
function farewell(name) { return 'goodbye, ' + name + '. enjoy your gzip-shaped present.'; }
function repeat(s, n) { let out = ''; for (let i = 0; i < n; i++) out += s; return out; }
function shout(s) { return s.toUpperCase() + '!'; }
function whisper(s) { return s.toLowerCase() + '...'; }
function count(arr) { return arr.length; }
function sum(arr) { return arr.reduce((a, b) => a + b, 0); }
function avg(arr) { return arr.length === 0 ? 0 : sum(arr) / arr.length; }
function min(arr) { return arr.reduce((a, b) => a < b ? a : b, Infinity); }
function max(arr) { return arr.reduce((a, b) => a > b ? a : b, -Infinity); }
function zip(a, b) { return a.map((x, i) => [x, b[i]]); }
function range(n) { return Array.from({length: n}, (_, i) => i); }
function uppercase(s) { return s.toUpperCase(); }
function lowercase(s) { return s.toLowerCase(); }
function firstChar(s) { return s.charAt(0); }
function lastChar(s) { return s.charAt(s.length - 1); }
export { greet, farewell, repeat, shout, whisper, count, sum, avg, min, max, zip, range, uppercase, lowercase, firstChar, lastChar };
